import React, {Component} from 'react';
import {Image, Text, TouchableNativeFeedback, View} from 'react-native';
import {bindActionCreators} from 'redux';
import {connect} from 'react-redux';
import styles from './ModalStyles';
import {showModal} from "../../Redux/App";
import {updateChallengeRequest} from "../../Redux/Playground/Challenge";

class ChallengeModal extends Component {
  startChallenge = () => {
    console.log("AAAAAAAAAAA "+this.props.app.challengeId.by);
    this.props.updateChallengeRequest({received: true, id: this.props.app.challengeId.challengeId, by: this.props.app.challengeId.by, chl_by: this.props.app.challengeId.by_username, to: this.props.app.challengeId.by_username, questions: this.props.app.challengeId.question_count, subject: this.props.app.challengeId.subject, chl_class: this.props.app.challengeId.standard, chapter: this.props.app.challengeId.topic });
    //this.props.updateChallengeRequest({received: true, id: this.props.app.challengeId.challengeId, chl_by: this.props.app.challengeId.by_username});
    //this.props.updateChallengeRequest({received: true});
    console.log("working");
    this.props.history.push('/challenge/loading');
  };

  render() {
    console.log("AAAAAAAAAAABB: "+JSON.stringify(this.props.app.challengeId));
    const {by, topic} = this.props.app.challengeId;
    return (
      <View style={styles.challengeModal}>
        <View style={styles.challengeTopSection}>
          <Image
            style={styles.challengedIcon}
            resizeMode={'contain'}
            source={{uri: 'data:image/png;base64,'}}
          />
          <Text style={styles.challengeTopSectionText}>
            {by} challenged you in {topic}
          </Text>
        </View>
        <View style={styles.challengeBottomSection}>
          <Text style={styles.challengeAcceptText}>Do you want to accept this challenge?</Text>
          <View style={styles.challengeButtonContainer}>
            <TouchableNativeFeedback
              onPress={() => {
                this.props.showModal(null);
                this.startChallenge();
              }}
            >
              <View style={[styles.challengeModalButton, styles.challengeModalButtonLeft]}>
                <Text style={styles.challengeModalButtonText}>Yes</Text>
              </View>
            </TouchableNativeFeedback>
            <TouchableNativeFeedback
              onPress={() => {
                this.props.showModal(null);
              }}
            >
              <View style={styles.challengeModalButton}>
                <Text style={[styles.challengeModalButtonText, {color: 'white'}]}>No</Text>
              </View>
            </TouchableNativeFeedback>
          </View>
        </View>
      </View>
    )
  }

}

const mapStateToProps = state => ({
  app: state.app,
});
const mapDispatchToProps = dispatch => bindActionCreators({
  showModal: showModal,
  updateChallengeRequest: updateChallengeRequest,
}, dispatch);

export default connect(mapStateToProps, mapDispatchToProps)(ChallengeModal);